CREATE OR REPLACE FUNCTION public.emargement_theorie_inscrite(p_apprenant_id uuid,p_session_id uuid DEFAULT NULL)
RETURNS TABLE(date_cours date,creneau text,debut time,fin time,pratique boolean)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
WITH app AS (SELECT a.*,upper(split_part(coalesce(a.type_apprenant,''),'-',1)) filiere,NOT(coalesce(a.creneau_horaire,'') ~* 'en[- ]?ligne|e[- ]?learning|online|distanciel' OR coalesce(a.type_apprenant,'') ~* '^(vtc|taxi|ta|va)-e$') presentiel FROM apprenants a WHERE a.id=p_apprenant_id AND a.deleted_at IS NULL AND NOT coalesce(a.abandonnee,false) AND coalesce(a.statut,'') !~* 'annul|abandon|exclu|attente'), inscriptions AS (
SELECT sa.*,s.type_session,s.nom,s.date_debut sd,s.date_fin sf,
coalesce(nullif(sa.heure_debut_personnalisee,''),nullif(s.heure_debut,''),CASE WHEN s.nom ~* 'soir' OR array_to_string(s.creneaux,' ') ~* 'soir|17' THEN '17:00' ELSE '09:00' END)::time hd,
coalesce(nullif(sa.heure_fin_personnalisee,''),nullif(s.heure_fin,''),CASE WHEN s.nom ~* 'soir' OR array_to_string(s.creneaux,' ') ~* 'soir|17' THEN '21:00' ELSE '16:00' END)::time hf,
greatest(s.date_debut,coalesce(sa.date_debut,s.date_debut)) d,
least(coalesce(s.date_fin,s.date_debut),coalesce(sa.date_fin_personnalisee,sa.date_fin,s.date_fin,s.date_debut)) f
FROM session_apprenants sa JOIN sessions s ON s.id=sa.session_id WHERE sa.apprenant_id=p_apprenant_id AND (p_session_id IS NULL OR sa.session_id=p_session_id) AND NOT coalesce(sa.liste_attente,false) AND NOT coalesce(sa.emargements_exclus,false) AND coalesce(s.statut,'') !~* 'annul|abandon' AND coalesce(sa.statut_suivi,'') !~* 'annul|abandon|exclu|attente'
),bornes AS (SELECT 'matin'::text c,'00:00'::time a,'12:00'::time z UNION ALL SELECT 'apres_midi','13:00'::time,'17:00'::time UNION ALL SELECT 'soir_1','17:00'::time,'18:30'::time UNION ALL SELECT 'soir_2','18:30'::time,'23:59:59'::time),theorie AS (
SELECT g::date date_cours,k.c creneau,greatest(i.hd,k.a) debut,least(i.hf,k.z) fin,false pratique FROM inscriptions i CROSS JOIN app a CROSS JOIN LATERAL generate_series(i.d::timestamp,i.f::timestamp,interval '1 day') g CROSS JOIN LATERAL (
SELECT 'matin'::text c,'09:00'::time a,'12:00'::time z WHERE i.hd<'17:00' UNION ALL SELECT 'apres_midi','13:00'::time,CASE WHEN (coalesce(a.type_apprenant,'')||' '||coalesce(a.formation_choisie,'')||' '||coalesce(i.nom,'')) ~* 'continue|\mfc\M|fco' THEN '17:00'::time ELSE '16:00'::time END WHERE i.hd<'17:00' UNION ALL SELECT 'soir_1','17:00'::time,'18:30'::time WHERE i.hd>='17:00' UNION ALL SELECT 'soir_2','18:30'::time,'21:00'::time WHERE i.hd>='17:00'
) k WHERE i.type_session ~* 'theorique' AND a.presentiel AND extract(isodow from g)<=5 AND (a.filiere<>'TA' OR i.date_fin_personnalisee IS NOT NULL OR (SELECT count(*) FROM generate_series(i.d::timestamp,g,interval '1 day') x WHERE extract(isodow from x)<=5)<=5)
) SELECT date_cours,creneau,min(debut),max(fin),false FROM theorie WHERE fin>debut GROUP BY date_cours,creneau ORDER BY date_cours,min(debut) $$;
REVOKE ALL ON FUNCTION public.emargement_theorie_inscrite(uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.emargement_theorie_inscrite(uuid,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.emargement_creneaux_reels(p_apprenant_id uuid)
RETURNS TABLE(date_cours date,creneau text,debut time,fin time,pratique boolean)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
WITH app AS (SELECT a.*,upper(split_part(coalesce(a.type_apprenant,''),'-',1)) filiere,NOT(coalesce(a.creneau_horaire,'') ~* 'en[- ]?ligne|e[- ]?learning|online|distanciel' OR coalesce(a.type_apprenant,'') ~* '^(vtc|taxi|ta|va)-e$') presentiel FROM apprenants a WHERE a.id=p_apprenant_id AND a.deleted_at IS NULL AND NOT coalesce(a.abandonnee,false) AND coalesce(a.statut,'') !~* 'annul|abandon|exclu|attente'),inscriptions AS (
SELECT sa.*,s.type_session,s.nom,s.date_debut sd,s.date_fin sf,
coalesce(nullif(sa.heure_debut_personnalisee,''),nullif(s.heure_debut,''),CASE WHEN s.nom ~* 'soir' OR array_to_string(s.creneaux,' ') ~* 'soir|17' THEN '17:00' ELSE '09:00' END)::time hd,
coalesce(nullif(sa.heure_fin_personnalisee,''),nullif(s.heure_fin,''),CASE WHEN s.nom ~* 'soir' OR array_to_string(s.creneaux,' ') ~* 'soir|17' THEN '21:00' ELSE '16:00' END)::time hf,
greatest(s.date_debut,coalesce(sa.date_debut,s.date_debut)) d,least(coalesce(s.date_fin,s.date_debut),coalesce(sa.date_fin_personnalisee,sa.date_fin,s.date_fin,s.date_debut)) f
FROM session_apprenants sa JOIN sessions s ON s.id=sa.session_id WHERE sa.apprenant_id=p_apprenant_id AND NOT coalesce(sa.liste_attente,false) AND NOT coalesce(sa.emargements_exclus,false) AND coalesce(s.statut,'') !~* 'annul|abandon' AND coalesce(sa.statut_suivi,'') !~* 'annul|abandon|exclu|attente'),bornes AS (
SELECT 'matin'::text c,'00:00'::time a,'12:00'::time z UNION ALL SELECT 'apres_midi','13:00'::time,'17:00'::time UNION ALL SELECT 'soir_1','17:00'::time,'18:30'::time UNION ALL SELECT 'soir_2','18:30'::time,'23:59:59'::time),theorie AS (SELECT * FROM public.emargement_theorie_inscrite(p_apprenant_id)),pratique_inscrite AS (
SELECT i.sd,k.c,greatest(coalesce(nullif(i.heure_debut_personnalisee,'')::time,p.debut,i.hd),k.a),least(coalesce(nullif(i.heure_fin_personnalisee,'')::time,p.fin,i.hf),k.z),true FROM inscriptions i CROSS JOIN app a CROSS JOIN bornes k LEFT JOIN reservations_pratique r ON r.apprenant_id=p_apprenant_id AND r.date_choisie=i.sd LEFT JOIN LATERAL pratique_creneaux_planifies(i.sd,coalesce(r.creneau,'journee')) p ON p.creneau=k.c WHERE i.type_session ~* 'pratique' AND k.c IN('matin','apres_midi') AND(r.id IS NULL OR p.creneau IS NOT NULL)),pratique_reservee AS (
SELECT r.date_choisie,p.creneau,p.debut,p.fin,true FROM reservations_pratique r CROSS JOIN app a CROSS JOIN LATERAL pratique_creneaux_planifies(r.date_choisie,r.creneau) p WHERE r.apprenant_id=p_apprenant_id AND NOT EXISTS(SELECT 1 FROM session_apprenants sa JOIN sessions s ON s.id=sa.session_id WHERE sa.apprenant_id=p_apprenant_id AND s.type_session ~* 'pratique' AND s.date_debut=r.date_choisie)),tous AS (
SELECT * FROM theorie UNION ALL SELECT * FROM pratique_inscrite UNION ALL SELECT * FROM pratique_reservee)
SELECT date_cours,creneau,min(debut),max(fin),bool_or(pratique) FROM tous WHERE debut IS NOT NULL AND fin>debut GROUP BY date_cours,creneau ORDER BY date_cours,min(debut) $$;
REVOKE ALL ON FUNCTION public.emargement_creneaux_reels(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.emargement_creneaux_reels(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.emargement_controle_creneau(p_apprenant_id uuid,p_date date,p_creneau text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT jsonb_build_object('autorise',r.date_cours=(now() AT TIME ZONE 'Europe/Paris')::date AND public.emargement_fenetre_ouverte(r.date_cours,r.debut,now()),'debut',r.debut,'fin',r.fin,'pratique',r.pratique,'ouvre_le',((r.date_cours+r.debut) AT TIME ZONE 'Europe/Paris')-interval '30 minutes') FROM public.emargement_creneaux_reels(p_apprenant_id) r WHERE r.date_cours=p_date AND r.creneau=p_creneau),jsonb_build_object('autorise',false,'motif','Créneau non prévu pour cette inscription')) $$;
REVOKE ALL ON FUNCTION public.emargement_controle_creneau(uuid,date,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.emargement_controle_creneau(uuid,date,text) TO service_role;
CREATE OR REPLACE FUNCTION public.emargement_fenetres_eleve(p_apprenant_id uuid) RETURNS TABLE(date_cours date,creneau text,debut time,fin time,pratique boolean,ouvre_le timestamptz,serveur_le timestamptz,ouverte boolean) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT(public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM apprenants a WHERE a.id=p_apprenant_id AND a.auth_user_id=auth.uid()) OR public.est_dossier_lie_emargement(p_apprenant_id)) THEN RAISE EXCEPTION 'Accès aux feuilles refusé' USING ERRCODE='42501'; END IF; RETURN QUERY SELECT r.date_cours,r.creneau,r.debut,r.fin,r.pratique,((r.date_cours+r.debut) AT TIME ZONE 'Europe/Paris')-interval '30 minutes',now(),r.date_cours=(now() AT TIME ZONE 'Europe/Paris')::date AND public.emargement_fenetre_ouverte(r.date_cours,r.debut,now()) FROM public.emargement_creneaux_reels(p_apprenant_id) r WHERE r.date_cours<=(now() AT TIME ZONE 'Europe/Paris')::date+1; END $$;
REVOKE ALL ON FUNCTION public.emargement_fenetres_eleve(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.emargement_fenetres_eleve(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.garde_emargement_fenetre() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r jsonb; BEGIN
IF TG_OP='UPDATE' AND (nullif(trim(coalesce(OLD.signature_data_url,'')),'') IS NOT NULL OR coalesce(OLD.absent,false)) AND (
NEW.signature_data_url IS DISTINCT FROM OLD.signature_data_url OR NEW.absent IS DISTINCT FROM OLD.absent OR NEW.date_emargement IS DISTINCT FROM OLD.date_emargement OR NEW.demi_journee IS DISTINCT FROM OLD.demi_journee OR NEW.apprenant_id IS DISTINCT FROM OLD.apprenant_id OR NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.signed_at IS DISTINCT FROM OLD.signed_at OR NEW.regularisation_id IS DISTINCT FROM OLD.regularisation_id
) THEN RAISE EXCEPTION 'Signature enregistrée conservée : remplacement refusé' USING ERRCODE='P0541'; END IF;
IF nullif(trim(coalesce(NEW.signature_data_url,'')),'') IS NULL AND NOT coalesce(NEW.absent,false) THEN RETURN NEW; END IF;
IF TG_OP='UPDATE' AND NEW.signature_data_url IS NOT DISTINCT FROM OLD.signature_data_url AND NEW.absent IS NOT DISTINCT FROM OLD.absent AND NEW.date_emargement IS NOT DISTINCT FROM OLD.date_emargement AND NEW.demi_journee IS NOT DISTINCT FROM OLD.demi_journee THEN RETURN NEW; END IF;
IF TG_OP='UPDATE' AND(nullif(trim(coalesce(OLD.signature_data_url,'')),'') IS NOT NULL OR coalesce(OLD.absent,false)) THEN RAISE EXCEPTION 'Signature enregistrée conservée : remplacement refusé' USING ERRCODE='P0541'; END IF;
IF NEW.regularisation_id IS NOT NULL AND EXISTS(SELECT 1 FROM emargement_regularisations e WHERE e.id=NEW.regularisation_id AND e.apprenant_id=NEW.apprenant_id AND e.auth_user_id=NEW.user_id AND e.expire_le>=now() AND e.creneaux @> jsonb_build_array(jsonb_build_object('date',NEW.date_emargement::text,'creneau',NEW.demi_journee)) AND NEW.date_emargement<(now() AT TIME ZONE 'Europe/Paris')::date) THEN NEW.signed_at:=clock_timestamp(); RETURN NEW; END IF;
r:=public.emargement_controle_creneau(NEW.apprenant_id,NEW.date_emargement,NEW.demi_journee);
IF coalesce((r->>'autorise')::boolean,false) IS NOT TRUE THEN RAISE EXCEPTION 'Signature refusée : créneau non prévu ou ouverture trente minutes avant le début réel non atteinte' USING ERRCODE='P0541'; END IF;
NEW.signed_at:=clock_timestamp(); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.garde_emargement_fenetre() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.garde_emargement_fenetre() TO service_role;
CREATE OR REPLACE FUNCTION public.generer_emargements_session(p_session_id uuid) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a record; p record; nb integer:=0; BEGIN
FOR a IN SELECT DISTINCT sa.apprenant_id,ap.auth_user_id FROM session_apprenants sa JOIN apprenants ap ON ap.id=sa.apprenant_id JOIN sessions s ON s.id=sa.session_id WHERE sa.session_id=p_session_id AND s.type_session ~* 'theorique' AND ap.auth_user_id IS NOT NULL AND NOT coalesce(sa.liste_attente,false) AND NOT coalesce(sa.emargements_exclus,false) AND coalesce(s.statut,'') !~* 'annul|abandon' AND coalesce(sa.statut_suivi,'') !~* 'annul|abandon|exclu|attente' LOOP
FOR p IN SELECT * FROM public.emargement_theorie_inscrite(a.apprenant_id,p_session_id) WHERE date_cours>(now() AT TIME ZONE 'Europe/Paris')::date LOOP
INSERT INTO public.emargements_fc(apprenant_id,user_id,date_emargement,demi_journee) VALUES(a.apprenant_id,a.auth_user_id,p.date_cours,p.creneau) ON CONFLICT(apprenant_id,date_emargement,demi_journee) DO NOTHING;
IF FOUND THEN nb:=nb+1; END IF; END LOOP; END LOOP; RETURN nb; END $$;
COMMENT ON FUNCTION public.generer_emargements_session(uuid) IS 'Future empty enrollment-based weekday sheets only; no signatures or historical mutation, cross-enrollments deduplicated.';